using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Prefabs/UI/ProfileScreen.prefab (generated by ProfileScreenPrefabs, editable by hand) — the player's profile opened
/// from the Main Menu's profile icon: a picture slot, the usual combat strength (average of the four converted
/// attributes over every run), best / last run, and the music styles the player picks. ProfileScreenController fills it.
/// </summary>
public class ProfileScreenView : MonoBehaviour
{
    [System.Serializable]
    public class StatRow
    {
        public FightStatId stat;
        public Image icon;
        public TextMeshProUGUI label;
        public Image fill;
        public TextMeshProUGUI value;
    }

    public GameObject root;
    public TextMeshProUGUI titleText;
    [Tooltip("The player's picture: a placeholder until there is an avatar editor / portrait (tinted by the preferred style).")]
    public Image portrait;
    public TextMeshProUGUI lookText;
    public TextMeshProUGUI strengthHeader;
    public StatRow[] stats = System.Array.Empty<StatRow>();
    public TextMeshProUGUI summaryText;
    public TextMeshProUGUI lastRunText;
    public TextMeshProUGUI stylesHeader;
    public TextMeshProUGUI stylesText;
    public TextMeshProUGUI noteText;
    public Button backButton;
    public TextMeshProUGUI backLabel;
}
